// Une la configuración del nodo «Config base» con la que lee el CRM (panel /asistente).
// Si el CRM respondió, sus valores mandan (interruptor, teléfonos de prueba, horarios, límites) y
// aportan los servicios con precio; si no respondió o está apagado, valen los de «Config base».
const base = $('Config base').first().json;
const remote = $input.first().json ?? {};
const out = { ...base };

const crm = remote && typeof remote.config === 'object' && remote.config !== null ? remote : null;
if (crm) {
  for (const [clave, valor] of Object.entries(crm.config)) {
    if (valor !== undefined && valor !== null) out[clave] = valor;
  }
  out.bloques = crm.bloques ?? {};
  out.catalogo = crm.catalogo ?? {};
  out.sinTarifa = Array.isArray(crm.sinTarifa) ? crm.sinTarifa : [];
  out.instruccionesExtra = String(crm.instruccionesExtra ?? '');
  out.mensajeFallback = String(crm.mensajeFallback ?? '');
  out.mensajeSeguimiento = String(crm.mensajeSeguimiento ?? '');
  out.configOrigen = 'crm';
} else {
  out.configOrigen = base.crmConfigActivo === true ? 'base (el CRM no respondió)' : 'base';
}

return [{ json: out }];

// Normaliza el webhook de wppia (messages.upsert) o el disparo horario de seguimientos.
const cfg = $('Config').first().json;
const item = $input.first().json;
const digits = (v) => String(v ?? '').replace(/\D/g, '');
const last9 = (v) => digits(v).slice(-9);
const lista = (v) => String(v ?? '').split(/[,;\s]+/).map(last9).filter(Boolean);
const skip = (reason) => [{ json: { route: 'skip', reason } }];

// Disparo del Schedule Trigger: no trae body.
if (item.body === undefined) return [{ json: { route: 'scan' } }];

// Sin secreto configurado el webhook quedaría abierto a cualquiera: se descarta todo.
const secret = String(cfg.webhookSecret ?? '').trim();
if (!secret || secret === 'CAMBIAR') return skip('configurar_webhookSecret');
if (String(item.headers?.['x-webhook-secret'] ?? '') !== secret) return skip('secreto_invalido');

const body = item.body ?? {};
if (!['messages.upsert', 'messages.received'].includes(body.event)) return skip('evento_' + body.event);

const raw = Array.isArray(body.data?.messages) ? body.data.messages[0] : body.data?.messages;
if (!raw?.key) return skip('sin_mensaje');

const key = raw.key;
const jid = String(key.remoteJid ?? raw.remoteJid ?? '');
if (jid.endsWith('@g.us') || jid.includes('broadcast') || raw.broadcast === true) return skip('grupo_o_difusion');

const fromMe = key.fromMe === true;
// Con LID el remoteJid no es el teléfono: se usa el número real que informa wppia.
const phone = fromMe
  ? digits(jid.endsWith('@s.whatsapp.net') ? jid : key.senderPn || key.cleanedSenderPn || '')
  : digits(key.cleanedSenderPn || key.senderPn || (jid.endsWith('@s.whatsapp.net') ? jid : ''));
if (!phone) return skip('sin_telefono');

// Números que el bot nunca atiende.
const interno = last9(cfg.notificarA);
if (interno && last9(phone) === interno) return skip('numero_interno');
if (lista(cfg.excluir).includes(last9(phone))) return skip('excluido');
const prueba = lista(cfg.soloPrueba);
if (prueba.length && !prueba.includes(last9(phone))) return skip('fuera_de_la_lista_de_prueba');

// Desenvuelve mensajes efímeros / de una sola vista / documento con caption.
let m = raw.message ?? {};
for (let i = 0; i < 3; i++) {
  m = m.ephemeralMessage?.message ?? m.viewOnceMessage?.message ?? m.viewOnceMessageV2?.message
    ?? m.documentWithCaptionMessage?.message ?? m;
}

let kind;
let text = String(raw.messageBody ?? m.conversation ?? m.extendedTextMessage?.text ?? '').trim();
let seconds = 0;
let fileName = null;
let location = null;

if (m.reactionMessage || m.protocolMessage || m.senderKeyDistributionMessage) return skip('mensaje_de_sistema');
else if (m.audioMessage) { kind = 'audio'; seconds = Number(m.audioMessage.seconds) || 0; }
else if (m.imageMessage) { kind = 'image'; text = text || String(m.imageMessage.caption ?? ''); }
else if (m.videoMessage) { kind = 'video'; text = text || String(m.videoMessage.caption ?? ''); }
else if (m.documentMessage) {
  kind = 'document';
  fileName = m.documentMessage.fileName || m.documentMessage.title || null;
  text = text || String(m.documentMessage.caption ?? '');
}
else if (m.locationMessage) {
  kind = 'location';
  location = { lat: m.locationMessage.degreesLatitude, lng: m.locationMessage.degreesLongitude };
}
else if (m.contactMessage || m.contactsArrayMessage) kind = 'contact';
else if (m.stickerMessage) kind = 'sticker';
else if (text) kind = 'text';
else return skip('vacio');

return [{
  json: {
    route: fromMe ? 'fromMe' : 'inbound',
    phone,
    name: String(raw.pushName ?? '').trim(),
    messageId: String(key.id ?? raw.id ?? ''),
    kind,
    text,
    seconds,
    fileName,
    location,
    tsMs: Number(raw.messageTimestamp) ? Number(raw.messageTimestamp) * 1000 : Date.now(),
    // Lo que pide POST /api/decrypt-media de wppia para bajar el audio.
    rawForMedia: { key: { id: key.id }, message: raw.message },
  },
}];

// Mensaje saliente (fromMe): si no es eco del bot, una persona tomó el chat y el bot se calla.
const cfg = $('Config').first().json;
const msg = $('Normalizar mensaje').first().json;
const row = $input.first().json;
const now = Date.now();

let e = {};
try { e = row.estado ? JSON.parse(row.estado) : {}; } catch { e = {}; }

// wppia reenvía como fromMe lo que el propio bot envía: se ignora durante 90 s.
if (e.lastBotAt && now - e.lastBotAt < 90_000) {
  return [{ json: { guardar: false, motivo: 'eco_del_bot' } }];
}

const horas = Number(cfg.pausaHoras) > 0 ? Number(cfg.pausaHoras) : 8;
e.phone = msg.phone;
e.pausedUntil = now + horas * 3600e3;
e.humano = true;
e.lastHumanAt = now;

return [{ json: { guardar: true, phone: msg.phone, estado: JSON.stringify(e) } }];

// Decide si el bot responde este mensaje y actualiza la ficha del chat.
const cfg = $('Config').first().json;
const msg = $('Normalizar mensaje').first().json;
const row = $input.first().json;
const now = Date.now();

let e = {};
try { e = row.estado ? JSON.parse(row.estado) : {}; } catch { e = {}; }

const duplicado = (e.ids ?? []).includes(msg.messageId);
e.phone = msg.phone;
e.name = e.name || msg.name || '';
e.firstAt = e.firstAt || now;
e.stage = e.stage || 'NUEVO';
e.lastInAt = now;
e.inCount = (e.inCount || 0) + 1;
e.ids = [...(e.ids ?? []), msg.messageId].slice(-30);
e.hist = (e.hist ?? []).filter((t) => now - t < 3600e3);

let responder = true;
let motivo = null;
// Cortesías que cierran la charla ("gracias", "igualmente 🙏"): no se contestan para no sumar otro
// "quedamos a disposición". Un "ok / dale / perfecto" solo se ignora si el bot no había hecho una
// pregunta: si la hizo, es una respuesta ("¿Quiere avanzar?" → "Dale") y hay que atenderla.
const agradece = /^(?:\s*(?:muchas gracias|muchaa? gracias|mil gracias|gracias a (?:usted|vos|ustedes)|gracias|igualmente|jaja|ja|👍|🙏|🙌|😊|🫡|\.)\s*[,!.]*\s*)+$/i;
const asiente = /^(?:\s*(?:muchas gracias|gracias|igualmente|okey|okis|oka|ok|dale|listo|bueno|perfecto|excelente|genial|entendido|entiendo|👍|🙏|🙌|\.)\s*[,!.]*\s*)+$/i;
const trivial = { test: (t) => agradece.test(t) || (!e.ultimaPregunta && asiente.test(t)) };

if (duplicado) { responder = false; motivo = 'duplicado'; }
else if (cfg.botActivo === false) { responder = false; motivo = 'bot_apagado'; }
else if (e.pausedUntil && e.pausedUntil > now) { responder = false; motivo = 'pausado_por_persona'; }
else if (e.hist.length >= (Number(cfg.maxRespuestasPorHora) > 0 ? Number(cfg.maxRespuestasPorHora) : 10)) {
  // Corta cualquier bucle o abuso: tope de respuestas por hora (configurable, 10 por defecto).
  responder = false; motivo = 'limite_por_hora'; e.pausedUntil = now + 2 * 3600e3;
}
else if (msg.kind === 'text' && trivial.test(msg.text) && (e.botReplies || 0) > 0) {
  responder = false; motivo = 'mensaje_de_cortesia';
}
else if (msg.kind === 'sticker' && (e.botReplies || 0) > 0) {
  responder = false; motivo = 'sticker';
}

return [{ json: { ...msg, e, estado: JSON.stringify(e), responder, motivo } }];

// Unifica el texto del mensaje (texto, audio transcripto, adjunto, ubicación) y arma el buffer anti-ráfaga.
const base = $('Estado del chat').first().json;
const inp = $input.first().json;
const e = base.e;
const cap = base.text ? ' con el texto: "' + base.text + '"' : '';
let text;

switch (base.kind) {
  case 'audio':
    if (inp.audioLargo) text = '[AUDIO MUY LARGO, no se transcribió: pedile amablemente que lo resuma por escrito]';
    else if (typeof inp.text === 'string' && inp.text.trim()) text = '[Audio transcripto] ' + inp.text.trim();
    else text = '[AUDIO NO COMPRENDIDO, falló la transcripción: pedile que lo escriba]';
    break;
  case 'image': text = '[El cliente envió una imagen' + cap + ']'; break;
  case 'video': text = '[El cliente envió un video' + cap + ']'; break;
  case 'document': text = '[El cliente envió un documento' + (base.fileName ? ' llamado "' + base.fileName + '"' : '') + cap + ']'; break;
  case 'location': text = '[El cliente compartió su ubicación GPS]'; break;
  case 'contact': text = '[El cliente compartió un contacto]'; break;
  case 'sticker': text = '[El cliente envió un sticker]'; break;
  default: text = base.text;
}

// Adjuntos y ubicación quedan anotados para el equipo humano.
if (['image', 'document', 'video', 'location', 'contact'].includes(base.kind)) {
  e.adjuntos = [...(e.adjuntos ?? []), { tipo: base.kind, at: Date.now(), archivo: base.fileName ?? null }].slice(-20);
}
if (base.location) e.ubicacion = base.location;

// El texto nuevo se agrega al buffer dentro de la base (atómico): acá va solo este mensaje.
const buffer = text

return [{
  json: { ...base, text, e, estado: JSON.stringify(e), buffer, lastMsgId: base.messageId },
}];

// Tras la espera: la base devuelve fila (y vacía el buffer) solo a la ejecución del ÚLTIMO mensaje de la ráfaga.
const base = $('Texto final').first().json;
const row = $input.first().json;
const now = Date.now();

let e = base.e;
try { if (row.estado) e = JSON.parse(row.estado); } catch { /* usa el estado local */ }

if (String(row.lastMsgId ?? '') !== String(base.messageId)) {
  return [{ json: { continuar: false, motivo: 'llego_otro_mensaje' } }];
}
// Una persona pudo haber tomado el chat mientras esperábamos.
if (e.pausedUntil && e.pausedUntil > now) {
  return [{ json: { continuar: false, motivo: 'pausado_por_persona' } }];
}

const text = String(row.buffer ?? '').trim();
if (!text) return [{ json: { continuar: false, motivo: 'ya_consumido' } }];
return [{ json: { continuar: true, phone: base.phone, name: base.name, kind: base.kind, messageId: base.messageId, text, e } }];

// Arma el mensaje que recibe el modelo: texto del cliente + lo que ya sabemos + bloques autorizados.
const cfg = $('Config').first().json;
const ficha = $('Ficha de servicios').first().json;
const u = $('¿Último mensaje?').first().json;
const e = u.e ?? {};

// Etapa del lead en el tablero del CRM (si crmEtapasActivo y el CRM respondió).
let tablero = null;
try { const t = $('CRM: etapa del lead').first().json; if (t && t.found) tablero = t; } catch { tablero = null; }

const now = $now.setZone(cfg.zonaHoraria || 'America/Asuncion');
const hhmm = now.toFormat('HH:mm');
const dias = String(cfg.atencionDias ?? '1,2,3,4,5').split(',').map((d) => Number(d.trim()));
const enHorario = dias.includes(now.weekday) && hhmm >= cfg.atencionDesde && hhmm < cfg.atencionHasta;

const sent = Object.entries(e.bloques ?? {})
  .filter(([, t]) => Date.now() - t < 6 * 3600e3)
  .map(([k]) => k);

const lines = [
  '=== MENSAJE DEL CLIENTE ===',
  u.text,
  '',
  '=== AHORA ===',
  `${now.setLocale('es').toFormat("cccc dd/MM/yyyy HH:mm")} (hora de Paraguay)`,
  `El equipo humano está ${enHorario ? 'DENTRO' : 'FUERA'} del horario de atención (${cfg.atencionDesde} a ${cfg.atencionHasta}).`,
  '',
  '=== DATOS YA CONOCIDOS DE ESTA PERSONA ===',
  `Nombre de perfil de WhatsApp (NO lo uses como nombre; solo vale el que diga la persona): ${u.name || 'no informado'}`,
  `Etapa actual: ${e.stage || 'NUEVO'}`,
  tablero ? `Etapa en el tablero del equipo (CRM): ${tablero.stage}${tablero.changedByPerson ? ` (la puso ${tablero.changedBy || 'una persona del equipo'}: respetala y no la contradigas)` : ''}` : '',
  tablero?.isWon ? 'El equipo ya lo marcó como cliente ganado: no le vuelvas a vender la constitución; ayudalo y, si pide algo del trámite, derivá.' : '',
  tablero?.isLost ? 'El equipo lo marcó como no concretado: respondé con amabilidad lo que pregunte, sin insistir con la venta.' : '',
  `Mensajes del cliente hasta ahora: ${e.inCount || 1}`,
  `Respuestas del bot hasta ahora: ${e.botReplies || 0}${(e.botReplies || 0) > 0 ? ' (ya te presentaste: no repitas el saludo ni la presentación)' : ' (es tu primera respuesta)'}`,
  `Ya se le preguntó el rubro: ${e.rubroPreguntado || e.lead?.rubro ? 'sí (no lo vuelvas a preguntar)' : 'no'}`,
  e.lead?.tiene_eas ? 'Ya tiene una EAS constituida: no le ofrezcas crear otra.' : '',
  e.lastHumanAt ? `Una persona del equipo ya le escribió por este chat (${Math.max(1, Math.round((Date.now() - e.lastHumanAt) / 86400e3))} día(s) atrás): es un cliente en conversación con el Lic. Rojas. No le vuelvas a vender; respondé breve y, si pide algo del trámite, derivá.` : '',
  e.noSeguir ? 'Dijo que por ahora no le interesa: respondé lo que pregunte sin insistir con la venta.' : '',
  `Datos del interesado: ${JSON.stringify(e.lead ?? {})}`,
  e.ubicacion ? 'Ya compartió su ubicación GPS.' : '',
  e.brochureAt ? 'Ya se le enviaron en PDF la presentación de ROMEZ y el detalle de los servicios para EAS (creación, contabilidad mensual, libros y requisitos, con precios). No los vuelvas a ofrecer: si pregunta algo puntual, respondé con el bloque que corresponda.' : '',
  (e.adjuntos ?? []).length ? `Ya envió ${(e.adjuntos ?? []).length} adjunto(s) (imágenes/documentos).` : '',
  '',
  '=== BLOQUES YA ENVIADOS EN LAS ÚLTIMAS 6 HORAS (no los repitas salvo que los pida de nuevo) ===',
  sent.length ? sent.join(', ') : 'ninguno',
  '',
  '=== BLOQUES AUTORIZADOS (código: contenido) ===',
  ...Object.entries(ficha.catalogo).map(([k, v]) => `${k}: ${v}`),
  '',
  '=== TEMAS SIN TARIFA CARGADA (derivar a una persona, no inventar) ===',
  ...ficha.sinTarifa.map((t) => `- ${t}`),
  ...(ficha.instruccionesExtra ? ['', '=== INSTRUCCIONES ADICIONALES DEL ESTUDIO ===', ficha.instruccionesExtra] : []),
];

return [{ json: { phone: u.phone, name: u.name, aiInput: lines.filter((l) => l !== undefined).join('\n'), enHorario } }];

// Valida la salida del modelo, arma los mensajes a enviar y actualiza la ficha del chat.
const cfg = $('Config').first().json;
const ficha = $('Ficha de servicios').first().json;
const ctx = $('Armar contexto IA').first().json;
const last = $('¿Último mensaje?').first().json;
const e = last.e ?? {};
const ai = $input.first().json ?? {};
const now = Date.now();

const STAGES = ['NUEVO', 'CALIFICANDO', 'COSTOS_ENVIADOS', 'DOCUMENTACION', 'LISTO_PARA_INICIAR', 'DERIVADO', 'DESCARTADO'];
const clean = (v) => String(v ?? '').replace(/\r/g, '').trim();
const SIN_IA = ficha.mensajeFallback || 'Disculpe, en este momento no puedo darle la información. Le paso con el Lic. José Rojas, que le responde a la brevedad 🙏';
const textoCliente = clean(last.text);

// 1) Parseo tolerante (el modelo puede envolver el JSON en ```).
const rawOut = clean(ai.output ?? ai.text ?? '');
let p = null;
try {
  const i = rawOut.indexOf('{');
  const j = rawOut.lastIndexOf('}');
  p = JSON.parse(rawOut.slice(i, j + 1));
} catch { p = null; }
const fallback = p === null;
if (fallback) p = { needs_human: true, human_reason: 'FALLA_IA', reply_parts: [SIN_IA], blocks: [], stage: 'DERIVADO' };

// 2) Red de seguridad: un precio escrito "a mano" por el modelo se descarta (solo valen los bloques).
const tienePrecio = (t) => /\bGs\.?\s*\d|\d{1,3}(?:\.\d{3})+/.test(t);
const descartados = [];
let parts = (Array.isArray(p.reply_parts) ? p.reply_parts : [])
  .map(clean).filter(Boolean)
  .filter((t) => { if (tienePrecio(t)) { descartados.push(t); return false; } return true; });
let closing = clean(p.closing);
if (tienePrecio(closing)) { descartados.push(closing); closing = ''; }

// 3) Bloques: solo códigos conocidos y no repetidos en 6 h.
const bloquesPrevios = e.bloques ?? {};
const bloques = [...new Set(Array.isArray(p.blocks) ? p.blocks : [])]
  .filter((k) => ficha.bloques[k] && !(bloquesPrevios[k] && now - bloquesPrevios[k] < 6 * 3600e3))
  .slice(0, 3);

let needsHuman = p.needs_human === true;
let reason = clean(p.human_reason) || null;

// 4) Claves por WhatsApp: el cliente nunca debe mandarlas y no se reenvían en el aviso.
// Una clave escrita ("clave: abc123", "contraseña Pepe2024") o el par usuario/clave típico ("3955602 / Accidente11").
// Preguntar por una clave ("¿necesito clave de Marangatu?") no dispara el aviso.
const PATRON_CLAVE = /\b(clave|contrase(?:ñ|n)a|password)\b\s*(?:es|de acceso)?\s*[:=]?\s*(?=\S*\d)(?=\S*[a-zA-Z])\S{5,}|\b\d{6,8}\s*[\/|]\s*(?=\S*[a-zA-Z])(?=\S*\d)\S{6,}/i;
const envioClaves = PATRON_CLAVE.test(textoCliente);
const AVISO_CLAVES = 'Por su seguridad, le pedimos que no envíe claves ni contraseñas por WhatsApp. El Lic. José Rojas le indicará cómo hacerlo de forma segura 🔒';
if (envioClaves) { needsHuman = true; reason = reason || 'ENVIO_CLAVES'; }

// Si descartamos un precio y no queda nada útil, mejor una persona.
if (!parts.length && !bloques.length && !closing) {
  needsHuman = true; reason = reason || 'SIN_RESPUESTA_UTIL';
  parts.push(descartados.length ? 'Permítame un momento, le paso con el Lic. José Rojas para confirmarle ese dato 🙏' : SIN_IA);
}

// 5) Sin presentación repetida: después de la primera respuesta el bot no vuelve a decir quién es.
const PRESENTACION = /^(?:(?:hola|buen(?:os|as)\s*(?:d[ií]as|tardes|noches)?)[,!. ]*)?soy (?:el )?asistente virtual de (?:la )?consultora romez[.,!]?\s*/i;
if ((e.botReplies || 0) > 0) parts = parts.map((t) => t.replace(PRESENTACION, '').trim()).filter(Boolean);

// 6) El rubro se pregunta UNA sola vez y nunca si ya se sabe, si ya tiene EAS o si se deriva.
const PREGUNTA_RUBRO = /rubro|a qu[eé] se dedica|actividad (principal|econ[oó]mica)?|qu[eé] actividad/i;
const esPregunta = (t) => /\?\s*$/.test(clean(t)) || /¿[^?]*\?/.test(clean(t));
const lead = { ...(e.lead ?? {}) };
for (const [k, v] of Object.entries(p.lead ?? {})) {
  if (v !== null && v !== undefined && clean(v) !== '') lead[k] = v;
}
const rubroBloqueado = Boolean(e.rubroPreguntado || lead.rubro || lead.tiene_eas === true || needsHuman);
const preguntaRubro = (t) => esPregunta(t) && PREGUNTA_RUBRO.test(t);
if (rubroBloqueado) {
  parts = parts.filter((t) => !preguntaRubro(t));
  if (preguntaRubro(closing)) closing = '';
}

// 7) Presentación y brochure en PDF: la primera vez que toca información de la EAS, en lugar de
// los textos largos se envía un mensaje de presentación y los dos PDF (en ese orden).
const EAS_INFO = ['EAS_COSTO', 'EAS_CONTABLE', 'EAS_LIBROS', 'EAS_REQUISITOS'];
const brochures = Array.isArray(ficha.brochures) ? ficha.brochures.filter((b) => b && b.url) : [];
const usarBrochure = brochures.length > 0 && !e.brochureAt && !needsHuman && bloques.some((k) => EAS_INFO.includes(k));
const bloquesTexto = usarBrochure ? bloques.filter((k) => !EAS_INFO.includes(k)) : bloques;
const INTRO_BROCHURE = 'Le comparto nuestra presentación institucional y el detalle de nuestros servicios para EAS, con la inversión, qué incluye, el plazo y los requisitos 📎';
const PREGUNTA_RUBRO_BROCHURE = '¿A qué se dedicaría la empresa? Así le confirmo que la EAS le conviene 🙌';
const CIERRE_BROCHURE = '¿Tiene alguna consulta o le gustaría avanzar con la constitución de su EAS?';

// Lo que anuncia un envío ("le envío…", "le comparto…") sobra cuando el sistema ya manda bloques o PDF.
const ANUNCIO = /\b(le|les) (env[ií]o|comparto|paso|dejo|mando|adjunto)\b|\ba continuaci[oó]n\b/i;
const hayEnvio = bloquesTexto.length > 0 || usarBrochure;
if (hayEnvio) parts = parts.filter((t) => !ANUNCIO.test(t));
// reply_parts nunca termina en pregunta: la única pregunta del turno va en el cierre.
const preguntaEnParts = parts.find(esPregunta);
parts = parts.filter((t) => !esPregunta(t));
if (!closing && preguntaEnParts && !needsHuman) closing = preguntaEnParts;
// Como máximo 1 mensaje propio si se envían bloques o PDF, 2 si no.
parts = parts.slice(0, hayEnvio ? 1 : 2);

let closingFinal = closing;
if (usarBrochure) {
  closingFinal = !rubroBloqueado ? PREGUNTA_RUBRO_BROCHURE : CIERRE_BROCHURE;
}
if (needsHuman && closingFinal && esPregunta(closingFinal)) closingFinal = '';
const preguntoRubroAhora = !rubroBloqueado && preguntaRubro(closingFinal);

const to = '+' + ctx.phone;
// Red final: nunca dos mensajes de texto iguales (ignorando mayúsculas, signos y espacios).
const firma = (t) => clean(t).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const vistos = new Set();
const mensajes = [
  ...(envioClaves ? [{ to, text: AVISO_CLAVES }] : []),
  ...parts.map((text) => ({ to, text })),
  ...(usarBrochure
    ? [{ to, text: INTRO_BROCHURE }, ...brochures.map((b) => ({ to, documentUrl: b.url, fileName: b.fileName }))]
    : []),
  ...bloquesTexto.map((k) => ({ to, text: ficha.bloques[k] })),
  ...(closingFinal ? [{ to, text: closingFinal }] : []),
].filter((m) => { if (!m.text) return true; const f = firma(m.text); if (vistos.has(f)) return false; vistos.add(f); return true; });

// 8) Ficha del chat.
e.lead = lead;
if (!e.name && e.lead?.nombre) e.name = e.lead.nombre;
e.intent = clean(p.intent) || e.intent || null;
e.stage = needsHuman ? 'DERIVADO' : (STAGES.includes(p.stage) ? p.stage : (e.stage || 'CALIFICANDO'));
if (bloques.includes('EAS_COSTO') || usarBrochure) e.priced = true;
if (usarBrochure) e.brochureAt = now;
if (preguntoRubroAhora) e.rubroPreguntado = now;
// Si el bot cerró con una pregunta, un "ok / dale" siguiente es una respuesta (ver «Estado del chat»).
e.ultimaPregunta = Boolean(closingFinal && esPregunta(closingFinal));
e.bloques = { ...bloquesPrevios };
for (const k of bloques) e.bloques[k] = now;
e.hist = [...(e.hist ?? []), now];
e.botReplies = (e.botReplies || 0) + 1;
e.lastBotAt = now;
e.lastOutAt = now;

// Seguimiento: el cliente que dice "por ahora no" no recibe más recordatorios; el que dice
// "lo analizo / les aviso" recibe como mucho uno, a partir de los 5 días.
const NO_INTERESA = /\b(no me interesa|por ahora no|no gracias|no estoy interesad|prefiero (otra|otro)|vi opciones m[aá]s econ[oó]micas|es (muy )?caro|precio (ya )?(es )?elevado|ya tengo (contador|con otro)|ya estoy tramitando)\b/i;
const MAS_ADELANTE = /\b(lo analizo|lo voy a analizar|analizando|lo pienso|lo voy a pensar|les? aviso|te aviso|le confirmo|le contacto|les contacto|me comunico|lo hablo|lo consulto|m[aá]s adelante|la semana (que viene|entrante|pr[oó]xima)|el (a[nñ]o|mes) que viene|mañana (le|te) paso|cuando pueda)\b/i;
if (NO_INTERESA.test(textoCliente) || e.stage === 'DESCARTADO') e.noSeguir = true;
else if (MAS_ADELANTE.test(textoCliente)) e.seguirDesde = now + 5 * 86400e3;

if (needsHuman) {
  const horas = Number(cfg.pausaHoras) > 0 ? Number(cfg.pausaHoras) : 8;
  e.pausedUntil = now + horas * 3600e3;
  e.derivadoMotivo = reason;
}

// 9) Aviso interno y sincronización opcional con el CRM.
const MOTIVOS = { OBJECION_PRECIO: 'Objeción de precio (conviene llamarlo)', ENVIO_CLAVES: 'Mandó claves por WhatsApp (no reenviarlas)' };
const ultimoParaAviso = envioClaves ? '[contenido oculto: el cliente envió claves]' : textoCliente.slice(0, 300);
const aviso = needsHuman
  ? [
      '🔔 Lead para atender',
      `Nombre: ${lead.nombre || 'sin dato'}${e.name && e.name !== lead.nombre ? ` (perfil: ${e.name})` : ''}`,
      `Teléfono: +${ctx.phone}`,
      `Interés: ${lead.tipo || e.intent || 'sin dato'}${lead.rubro ? ' · rubro: ' + lead.rubro : ''}${lead.tiene_eas ? ' · ya tiene EAS' : ''}`,
      `Motivo: ${MOTIVOS[reason] || reason || 'sin dato'}`,
      `Etapa: ${e.stage}${e.brochureAt ? ' · ya recibió los PDF' : ''}`,
      `Último mensaje: "${ultimoParaAviso}"`,
      ctx.enHorario ? '' : '(Entró fuera de horario de atención)',
    ].filter(Boolean).join('\n')
  : '';

// Número del equipo en formato internacional. Un número local paraguayo (0981…/981…) se
// completa con 595: "+0981…" no existe y WhatsApp descarta el aviso sin dar error.
function avisoTo(v) {
  let d = String(v ?? '').replace(/\D/g, '');
  if (!d) return '';
  if (d.startsWith('00')) d = d.slice(2);
  else if (d.startsWith('0') && d.length === 10) d = '595' + d.slice(1);
  else if (d.startsWith('9') && d.length === 9) d = '595' + d;
  return '+' + d;
}

const crmSync = cfg.crmActivo === true && Boolean(lead.nombre || e.name);
const crm = crmSync ? {
  firstName: String(lead.nombre || e.name).slice(0, 80),
  phone: '+' + ctx.phone,
  source: 'WHATSAPP_COMERCIAL',
  tags: ['asistente-whatsapp', lead.tipo ? String(lead.tipo).toLowerCase() : 'consulta'],
  customData: { rubro: lead.rubro ?? null, ciudad: lead.ciudad ?? null, etapa: e.stage, tieneRuc: lead.tiene_ruc ?? null },
  upsert: true,
} : null;

return [{
  json: {
    phone: ctx.phone,
    mensajes,
    estado: JSON.stringify(e),
    handoff: needsHuman,
    aviso,
    avisoTo: avisoTo(cfg.notificarA),
    crmSync,
    crm,
    meta: { fallback, descartados, bloques, stage: e.stage, brochure: usarBrochure, envioClaves },
  },
}];

// Cada hora: recordatorios a quien no volvió a escribir. Como máximo 2 por chat en toda la charla:
// el primero a las `seguimientoHoras` del último mensaje del bot y, solo a quien ya recibió la
// información, un segundo a los 5 días ofreciendo una llamada. Nunca a quien dijo "por ahora no",
// a chats que ya atiende una persona ni a números internos.
const cfg = $('Config').first().json;
if (cfg.seguimientoActivo !== true || cfg.botActivo === false) return [];

const ahora = $now.setZone(cfg.zonaHoraria || 'America/Asuncion');
const hhmm = ahora.toFormat('HH:mm');
// Solo de lunes a viernes, aunque la oficina atienda los sábados.
const dias = String(cfg.atencionDias ?? '1,2,3,4,5').split(',').map((d) => Number(d.trim())).filter((d) => d >= 1 && d <= 5);
if (!dias.includes(ahora.weekday) || hhmm < cfg.seguimientoDesde || hhmm > cfg.seguimientoHasta) return [];

const last9 = (v) => String(v ?? '').replace(/\D/g, '').slice(-9);
const lista = (v) => String(v ?? '').split(/[,;\s]+/).map(last9).filter(Boolean);
const prueba = lista(cfg.soloPrueba);
const excluidos = [...lista(cfg.excluir), last9(cfg.notificarA)].filter(Boolean);

const now = Date.now();
const H = 3600e3;
const primero = (Number(cfg.seguimientoHoras) || 24) * H;
const SEGUNDO = 5 * 24 * H;
const SEGUIR = ['NUEVO', 'CALIFICANDO', 'COSTOS_ENVIADOS'];
const out = [];

const plantilla = (t, nombre) => t.split('{{nombre}}').join(nombre).replace(/ +,/g, ',').replace(/  +/g, ' ').trim();

for (const { json: row } of $input.all()) {
  if (!row?.estado) continue;
  let e;
  try { e = JSON.parse(row.estado); } catch { continue; }
  if (!e.phone || !SEGUIR.includes(e.stage)) continue;
  if (e.noSeguir || e.lastHumanAt) continue; // dijo que no, o ya lo atiende una persona
  if (e.pausedUntil && e.pausedUntil > now) continue;
  if (e.seguirDesde && e.seguirDesde > now) continue;
  if (!e.lastOutAt || !e.lastInAt || e.lastInAt > e.lastOutAt) continue; // el cliente habló último: no corresponde
  if (excluidos.includes(last9(e.phone))) continue;
  if (prueba.length && !prueba.includes(last9(e.phone))) continue;

  // Chats de antes de este cambio (sin `followUps`): si ya recibieron un seguimiento no reciben
  // más, porque no se sabe si después dijeron que no.
  if (e.followUps === undefined && e.followUpSent) continue;
  const enviados = Number(e.followUps) || 0;
  const recibioInfo = e.stage === 'COSTOS_ENVIADOS' || Boolean(e.brochureAt || e.priced);
  const silencio = now - e.lastOutAt;
  let tipo = null;
  if (enviados === 0 && silencio >= primero && silencio <= 72 * H) tipo = 'primero';
  else if (enviados === 1 && recibioInfo && silencio >= SEGUNDO && silencio <= 8 * 24 * H) tipo = 'segundo';
  if (!tipo) continue;

  // Solo el nombre que dijo la persona (el de perfil de WhatsApp suele ser un apodo o un comercio).
  const pila = String(e.lead?.nombre || '').trim().split(/\s+/)[0];
  const esNombre = /^[A-Za-zÁÉÍÓÚÑÜáéíóúñü]{3,15}$/.test(pila) && pila !== pila.toUpperCase()
    && !['abg', 'abog', 'dr', 'dra', 'lic', 'ing', 'sr', 'sra'].includes(pila.toLowerCase());
  const nombre = esNombre ? pila[0].toUpperCase() + pila.slice(1).toLowerCase() : '';

  let texto;
  if (tipo === 'segundo') {
    texto = 'Buenas {{nombre}}, ¿pudo avanzar con la decisión sobre su empresa? Si quiere, el Lic. José Rojas le llama para aclarar dudas, sin compromiso: solo responda «sí» 🙌';
  } else if (recibioInfo) {
    texto = cfg.mensajeSeguimiento || 'Buenas {{nombre}}, le escribe nuevamente el equipo de la Consultora ROMEZ. ¿Pudo revisar la información que le enviamos? Si le quedó alguna duda, con gusto se la resuelvo 🙌';
  } else {
    texto = 'Buenas {{nombre}}, le escribe nuevamente el equipo de la Consultora ROMEZ. ¿Le paso el costo y lo que incluye la creación de una EAS? 🙌';
  }

  e.followUps = enviados + 1;
  e.followUpSent = true;
  e.lastFollowUpAt = now;
  e.ultimaPregunta = true;
  e.lastOutAt = now;
  e.lastBotAt = now;
  out.push({ json: { phone: e.phone, to: '+' + e.phone, text: plantilla(texto, nombre), estado: JSON.stringify(e) } });
}
return out;
